# ---------------------------------------------------------------- MISSÕES DA HISTÓRIA (lineares)
# type: starter | collect | craft | build | capture | assign | boss | trainer | flag | visit | level | talk
def Q(qid, title_pt, title_en, desc_pt, desc_en, typ, target=None, count=1, marker=None, reward=None, dialog=None, done_dialog=None):
    return {"id": qid, "title": L(title_pt, title_en), "desc": L(desc_pt, desc_en), "type": typ, "target": target,
            "count": count, "marker": marker, "reward": reward or {}, "dialog": dialog, "done_dialog": done_dialog}


