DIALOGS = {
    "d_intro": D(
        ("eco", "...Sexta. Sexta, acorde. O Coração ainda bate. Fraco, mas bate.", "...Sixth. Sixth, wake up. The Heart still beats. Weakly, but it beats."),
        ("lume", "Ah! Você abriu os olhos! Eu sou Lume. Fui... programada para esperar por você. Por trezentos anos, aparentemente.", "Oh! You opened your eyes! I'm Lume. I was... programmed to wait for you. For three hundred years, apparently."),
        ("lume", "Você estava no Berço — uma cápsula de sono lumariana. Não lembra de nada, né? Era o plano. Seu plano.", "You were in the Cradle — a Lumarian sleep capsule. You don't remember anything, do you? That was the plan. Your plan."),
        ("lume", "Olhe ali: três Ecos presos em Coleiras de Silêncio. Os Regentes ainda caçam por aqui.", "Look there: three Echoes bound by Silence Collars. The Regents still hunt around here."),
        ("lume", "Só temos energia para romper uma coleira agora. Escolha com o coração. Os outros vão fugir para a mata — você poderá reencontrá-los.", "We only have power to break one collar right now. Choose with your heart. The others will flee into the woods — you can find them again."),
    ),
    "d_starter_done": D(
        ("lume", "Conseguiu! Sinta isso... é um Vínculo. Ecos nascem da memória do mundo e lembram de quem os liberta.", "You did it! Feel that... it's a Bond. Echoes are born from the world's memory, and they remember who frees them."),
        ("lume", "Este mundo se chama Ecoterra. E está doente. Precisamos de abrigo, ferramentas... e respostas.", "This world is called Ecoterra. And it's sick. We need shelter, tools... and answers."),
    ),
    "d_q02": D(("lume", "Primeiro o básico: toque nas árvores, pedras e capins para coletar. Seu Eco ajuda se ficar por perto.", "Basics first: tap trees, rocks and grass to gather. Your Echo helps if it stays close."),),
    "d_q03": D(("lume", "Abra o menu Criar. Ferramentas de pedra dobram sua velocidade de coleta.", "Open the Craft menu. Stone tools double your gathering speed."),),
    "d_q04": D(("lume", "Uma Bancada desbloqueia receitas melhores. Toque em Construir e escolha um lugar plano.", "A Workbench unlocks better recipes. Tap Build and pick a flat spot."),),
    "d_q05": D(("lume", "Esferas de Vínculo não aprisionam: elas oferecem um lar. Um Eco só aceita se confiar em você... ou estiver cansado demais para fugir.", "Bond Spheres don't imprison: they offer a home. An Echo only accepts if it trusts you... or is too tired to run."),),
    "d_q06": D(("lume", "Enfraqueça um Eco selvagem com seu parceiro e lance a Esfera. Quanto menos vida, maior a chance!", "Weaken a wild Echo with your partner and throw the Sphere. The lower its health, the better the odds!"),),
    "d_q06_done": D(("lume", "Uma equipe! Você pode trocar o Eco ativo pelo menu Ecos. Tipos diferentes formam Harmonia: mais dano para todos.", "A team! Swap your active Echo in the Echoes menu. Different types form Harmony: more damage for everyone."),),
    "d_q07": D(("lume", "Sua barriga está roncando. A fome cai devagar — coma para recuperar vida. Carne assada é muito melhor que crua.", "Your stomach is growling. Hunger drops slowly — eat to recover health. Roast meat beats raw meat."),),
    "d_q08": D(("lume", "A noite em Ecoterra é perigosa: Ecos de Sombra saem para caçar. Uma Cama é seu ponto de retorno, e dormir pula a noite.", "Night in Ecoterra is dangerous: Shade Echoes come out to hunt. A Bed is your respawn point, and sleeping skips the night."),),
    "d_q09": D(("lume", "Os Lumarianos viviam ao lado dos Ecos, não acima deles. Aloque um Eco numa estação e ele produz recursos — até quando você estiver longe!", "The Lumarians lived beside the Echoes, not above them. Assign an Echo to a station and it produces resources — even while you're away!"),),
    "d_q09_done": D(("lume", "Veja como ele trabalha feliz. Sem coleiras, sem chicotes. Nunca entendi por que os Regentes escolheram outro caminho...", "Look how happily it works. No collars, no whips. I never understood why the Regents chose another way..."),
                    ("lume", "...ou será que entendi, um dia? Às vezes tenho memórias que não parecem minhas.", "...or did I understand, once? Sometimes I have memories that don't feel like mine.")),
    "d_q10": D(("lume", "Sinto algo pulsando a oeste — a Seiva Ancestral. Mas uma muralha de espinhos protege a clareira. Fogo deve resolver.", "I sense something pulsing to the west — the Ancient Sap. But a wall of thorns guards the clearing. Fire should do it."),),
    "d_q11": D(("lume", "O Ancião Musgoso. Ele não é mau, só está... assustado. Derrote-o com cuidado. Talvez ele até aceite uma Esfera.", "The Mossy Elder. It isn't evil, just... frightened. Defeat it gently. It might even accept a Sphere."),),
    "d_q11_done": D(("lume", "A Seiva Ancestral! Uma das três chaves da Ponte Lumariana. As outras estão nas Dunas e nos Picos.", "The Ancient Sap! One of three keys to the Lumarian Bridge. The others lie in the Dunes and the Peaks."),
                    ("lume", "Quando você tocou a Seiva, eu... vi um laboratório. Seis pessoas. E uma delas era você.", "When you touched the Sap, I... saw a laboratory. Six people. And one of them was you.")),
    "d_q12": D(("lume", "Para o que vem pela frente precisamos de metal. Minério de ferro + carvão na Fornalha.", "For what lies ahead we need metal. Iron ore + coal in the Furnace."),),
    "d_q13": D(("lume", "As Dunas de Âmbar queimam durante o dia. Sem um Cantil, o calor vai drenar sua vida.", "The Amber Dunes burn by day. Without a Canteen the heat will drain your health."),),
    "d_q13_done": D(("lume", "Que calor! Ali, ao leste, há um templo antigo. A porta reage à luz do sol... concentrada.", "So hot! There, to the east, is an ancient temple. Its door reacts to sunlight... focused sunlight."),),
    "d_q14": D(("lume", "A Bancada Arcana combina tecnologia lumariana e cristais Eco. Com ela, criamos a Lente Solar.", "The Arcane Bench combines Lumarian technology and Echo crystals. With it, we can craft the Sun Lens."),),
    "d_q15": D(("lume", "Ambarraque guarda o Olho de Âmbar. Ataques de Gelo e Maré funcionam bem contra Terra.", "Ambarraque guards the Amber Eye. Frost and Tide attacks work well against Earth."),),
    "d_q15_done": D(("lume", "O Olho... ele me mostrou uma cidade de ferro e fumaça. Porto Ferrugem. Ecos acorrentados a máquinas.", "The Eye... it showed me a city of iron and smoke. Rustport. Echoes chained to machines."),),
    "d_q16": D(("lume", "Os Picos de Geada congelam até pensamentos. Um Casaco de Pele vai manter seu corpo aquecido.", "The Frost Peaks freeze even thoughts. A Fur Coat will keep you warm."),),
    "d_q17": D(("lume", "O muro da caverna é gelo eterno. Pedra não basta: precisamos de ferro. Construa uma Forja.", "The cave wall is eternal ice. Stone won't do: we need iron. Build a Forge."),),
    "d_q18": D(("lume", "Serpegelo chora cristais. Cada lágrima é uma memória congelada... talvez uma delas seja sua.", "Serpegelo weeps crystals. Each tear is a frozen memory... maybe one of them is yours."),),
    "d_q18_done": D(("lume", "As três relíquias! Seiva, Olho e Lágrima. Vida, luz e memória. Os Lumarianos construíram a ponte para que só alguém digno a abrisse.", "All three relics! Sap, Eye and Tear. Life, light and memory. The Lumarians built the bridge so only someone worthy could open it."),),
    "d_q19": D(("lume", "Na Bancada Arcana, una as três relíquias num Núcleo.", "At the Arcane Bench, unite the three relics into a Core."),),
    "d_q20": D(("lume", "O altar da ponte fica ao norte do Bosque, na costa. Coloque o Núcleo lá.", "The bridge altar lies north of the Grove, on the coast. Place the Core there."),),
    "d_q20_done": D(("lume", "Olhe! A Ponte Lumariana desperta! Do outro lado... Porto Ferrugem. O primeiro dos domínios dos Regentes.", "Look! The Lumarian Bridge awakens! On the other side... Rustport. The first of the Regents' domains."),),
    "d_vorn_meet": D(
        ("vorn", "Ora, ora. Um rosto que eu esperava nunca mais ver. A Sexta Regente, de volta dos mortos.", "Well, well. A face I hoped never to see again. The Sixth Regent, back from the dead."),
        ("vorn", "Não se lembra? Que conveniente. Foi VOCÊ quem projetou as Coleiras de Silêncio. Cada Eco acorrentado nesta cidade carrega a sua assinatura.", "You don't remember? How convenient. YOU designed the Silence Collars. Every chained Echo in this city carries your signature."),
        ("lume", "...Sexta, não dê ouvidos. Ele quer te quebrar.", "...Sixth, don't listen. He wants to break you."),
        ("vorn", "Liberte meus trabalhadores, se tiver coragem. Meus capitães vão esmagar seus bichinhos. E depois... conversaremos na arena.", "Free my workers, if you dare. My captains will crush your pets. And then... we'll talk in the arena."),
    ),
    "d_q22": D(("lume", "Há Ecos enjaulados pela cidade. Um Pé de Cabra abre as jaulas. Ecos libertos podem se juntar a você!", "There are caged Echoes all over the city. A Crowbar opens the cages. Freed Echoes may join you!"),),
    "d_q22_done": D(("lume", "Todos livres! Os moradores estão saindo das casas... estão olhando para você com esperança.", "All free! The townsfolk are leaving their homes... they're looking at you with hope."),),
    "d_q23": D(("lume", "Os três capitães comandam os distritos. Derrote-os e Vorn ficará sem escudo.", "The three captains command the districts. Defeat them and Vorn loses his shield."),),
    "d_q24": D(("lume", "É agora. O Ferro-Colosso está acorrentado ao coração da fundição. Se vencermos, podemos libertá-lo também.", "This is it. The Iron Colossus is chained to the foundry's heart. If we win, we can free it too."),),
    "d_rasha_intro": D(("rasha", "As docas são minhas! Nenhum navio sai sem a permissão do Barão.", "The docks are mine! No ship leaves without the Baron's permission."),),
    "d_rasha_defeat": D(("rasha", "...Talvez o mar deva ser livre, afinal. Vá. A balsa é sua quando tudo acabar.", "...Maybe the sea should be free after all. Go. The ferry is yours when this is over."),),
    "d_brutus_intro": D(("brutus", "Na fundição a gente trabalha até o metal ceder. Ou os Ecos.", "In the foundry we work until the metal gives. Or the Echoes do."),),
    "d_brutus_defeat": D(("brutus", "Eu... só segui ordens. Isso não é desculpa, é?", "I... just followed orders. That's no excuse, is it?"),),
    "d_lin_intro": D(("lin", "Eu mantenho as coleiras funcionando. Fui sua aluna, sabia? Você me ensinou tudo.", "I keep the collars running. I was your student, did you know? You taught me everything."),),
    "d_lin_defeat": D(("lin", "Você mudou. Ou voltou a ser quem era antes de nos ensinar a acorrentar. Tome — o código mestre das coleiras desta cidade.", "You've changed. Or gone back to who you were before you taught us to chain. Take this — the master code for this city's collars."),),
    "d_vorn_intro": D(("vorn", "Você não entende, Sexta! Sem as coleiras, a Fúria Cinza volta. Os Ecos enlouquecem. Nós SALVAMOS este mundo!", "You don't understand, Sixth! Without the collars, the Grey Fury returns. The Echoes go mad. We SAVED this world!"),),
    "d_vorn_defeat": D(
        ("vorn", "Impossível... Os Ecos lutaram por você sem coleira nenhuma...", "Impossible... The Echoes fought for you without any collar..."),
        ("vorn", "Pergunte à Imperatriz Sable em Alta Cinza de onde vem a Fúria. Pergunte o que a Regência tira do Coração toda noite.", "Ask Empress Sable in Ashspire where the Fury comes from. Ask what the Regency takes from the Heart every night."),
    ),
    "d_act1_end": D(
        ("lume", "A coleira do Ferro-Colosso se partiu! Ele... quer vir com você.", "The Iron Colossus's collar has broken! It... wants to come with you."),
        ("lume", "Porto Ferrugem está livre. Os moradores abriram o mercado e o quadro de missões. Aqui será nossa casa.", "Rustport is free. The townsfolk opened the market and the quest board. This will be our home."),
        ("lume", "Sexta... eu recuperei outra memória. Nela, você dizia: 'Se eu esquecer, Lume, me lembre de que a culpa é minha — e o conserto também.'", "Sixth... I recovered another memory. In it, you said: 'If I forget, Lume, remind me the fault is mine — and so is the fix.'"),
        ("lume", "Fim do Ato 1. A balsa nas Docas leva às Terras Cinzentas.", "End of Act 1. The ferry at the Docks leads to the Grey Lands."),
    ),
    "d_q25": D(("iara", "Você é quem libertou a cidade? A balsa é sua. Mas o Pântano Lúgubre não perdoa quem respira seus gases.", "You're the one who freed the city? The ferry is yours. But the Gloom Marsh doesn't forgive those who breathe its gases."),),
    "d_q25_done": D(("lume", "Este pântano... era uma floresta. A Regência drenou o Coração daqui primeiro. Veja as árvores mortas.", "This marsh... was a forest. The Regency drained the Heart here first. Look at the dead trees."),),
    "d_q26": D(("lume", "Vidro, pele e lodo: uma Máscara de Filtro nos mantém respirando.", "Glass, hide and mud: a Filter Mask keeps us breathing."),),
    "d_q27": D(("lume", "Lodorei engoliu a Raiz Negra para escondê-la de Sable. Ele está protegendo, não atacando.", "Lodorei swallowed the Black Root to hide it from Sable. It's protecting, not attacking."),),
    "d_q27_done": D(("lume", "A Raiz Negra absorve luz... e Fúria. Sexta, acho que a Fúria Cinza não vem dos Ecos. Ela vem do Coração ferido.", "The Black Root absorbs light... and Fury. Sixth, I think the Grey Fury doesn't come from the Echoes. It comes from the wounded Heart."),),
    "d_q28": D(("lume", "O Cânion Brasa derrete ferro comum. Obsidiana + ferro forma uma liga resistente.", "Ember Canyon melts common iron. Obsidian + iron forms a resilient alloy."),),
    "d_q29": D(("lume", "Magmarca tem a Brasa Eterna no peito. Ataques de Maré e Terra vão ajudar.", "Magmarca holds the Eternal Ember in its chest. Tide and Earth attacks will help."),),
    "d_q29_done": D(("lume", "Outra memória: você e Tessár, o Grão-Regente, discutindo. 'As coleiras eram temporárias!', você gritava.", "Another memory: you and Tessár, the High Regent, arguing. 'The collars were meant to be temporary!' you shouted."),),
    "d_q30": D(("lume", "As Ilhas Tempestade são atingidas por raios o tempo todo. Precisamos de um Para-raios.", "The Storm Isles are struck by lightning constantly. We need a Lightning Rod."),),
    "d_q31": D(("lume", "Trovaguia nunca foi tocado por ninguém. Mostre que você não quer possuí-lo.", "No one has ever touched Trovaguia. Show it you don't want to own it."),),
    "d_q31_done": D(("lume", "As três relíquias das Terras Cinzentas! Agora a Chave Sombria pode ser forjada.", "All three relics of the Grey Lands! Now the Shadow Key can be forged."),),
    "d_q32": D(("lume", "O portão norte do Pântano leva a Alta Cinza. Sable vigia tudo através dos olhos de Umbra.", "The Marsh's north gate leads to Ashspire. Sable watches everything through Umbra's eyes."),),
    "d_q33": D(("lume", "Alta Cinza é silenciosa demais. Os Ecos aqui foram proibidos até de fazer barulho.", "Ashspire is far too quiet. The Echoes here were forbidden even to make a sound."),),
    "d_sable_meet": D(
        ("sable", "A Sexta. Vorn sempre foi fraco. Eu não sou.", "The Sixth. Vorn was always weak. I am not."),
        ("sable", "Você quer a verdade? A Regência alimenta as cidades com a energia do Coração-Aurora. A Fúria é o grito dele. As coleiras abafam o grito.", "You want the truth? The Regency powers the cities with the Aurora Heart's energy. The Fury is its scream. The collars muffle the scream."),
        ("sable", "E quem descobriu como abafá-lo... foi você.", "And the one who discovered how to muffle it... was you."),
    ),
    "d_q34": D(("lume", "Vex, Moira e Kade guardam o palácio. Cuidado: Sable aprende com cada luta que observa.", "Vex, Moira and Kade guard the palace. Careful: Sable learns from every fight she watches."),),
    "d_q35": D(("lume", "Seja qual for a verdade sobre o seu passado... os Ecos escolheram você. Isso diz quem você é agora.", "Whatever the truth about your past... the Echoes chose you. That says who you are now."),),
    "d_vex_intro": D(("vex", "Silêncio é ordem. Ordem é paz.", "Silence is order. Order is peace."),),
    "d_vex_defeat": D(("vex", "...Que barulho bonito eles fazem quando estão livres.", "...What a lovely noise they make when they're free."),),
    "d_moira_intro": D(("moira", "Eu curo os Ecos para que voltem às minas. É misericórdia.", "I heal the Echoes so they can return to the mines. It's mercy."),),
    "d_moira_defeat": D(("moira", "Misericórdia seria nunca tê-los mandado.", "Mercy would have been never sending them."),),
    "d_kade_intro": D(("kade", "Sable me deu um exército. Você me deu uma derrota que ainda não aconteceu.", "Sable gave me an army. You're about to give me a defeat that hasn't happened yet."),),
    "d_kade_defeat": D(("kade", "Um soldado sabe quando a guerra mudou de lado.", "A soldier knows when the war has changed sides."),),
    "d_sable_intro": D(("sable", "Mostre-me, Sexta, que um mundo sem coleiras não queima.", "Show me, Sixth, that a world without collars doesn't burn."),),
    "d_sable_defeat": D(
        ("sable", "...Umbra está ronronando. Há anos ela não fazia isso.", "...Umbra is purring. She hasn't done that in years."),
        ("sable", "Tessár espera por você na Cidadela Aurora. Ele guarda o Coração. E guarda a sua última memória.", "Tessár awaits you in the Aurora Citadel. He guards the Heart. And he guards your last memory."),
    ),
    "d_act2_end": D(
        ("lume", "Alta Cinza está livre. E eu... finalmente lembrei quem eu sou.", "Ashspire is free. And I... finally remember who I am."),
        ("lume", "Eu sou a parte de você que você apagou. Sua culpa, sua coragem. Você me guardou para não perder o caminho de volta.", "I'm the part of you that you erased. Your guilt, your courage. You kept me so you wouldn't lose the way back."),
        ("lume", "Fim do Ato 2. Talassa, Fornalha Rubra e a Cidadela Aurora chegam nas próximas atualizações.", "End of Act 2. Thalassa, Crimson Furnace and the Aurora Citadel arrive in upcoming updates."),
    ),
    "d_hazard_calor": D(("lume", "Este calor está drenando sua vida! Um Cantil de Couro vai proteger você.", "This heat is draining your health! A Leather Canteen will protect you."),),
    "d_hazard_frio": D(("lume", "Você está congelando! Precisamos de um Casaco de Pele.", "You're freezing! We need a Fur Coat."),),
    "d_hazard_veneno": D(("lume", "Os gases do pântano são tóxicos! Uma Máscara de Filtro resolve.", "The marsh gases are toxic! A Filter Mask solves it."),),
    "d_hazard_lava": D(("lume", "O calor do cânion é insuportável! Precisamos de um Traje Ignífugo.", "The canyon's heat is unbearable! We need a Fireproof Suit."),),
    "d_hazard_tempestade": D(("lume", "Raios! Sem um Para-raios Portátil não dá para ficar aqui.", "Lightning! Without a Lightning Rod we can't stay here."),),
    "d_night": D(("lume", "A noite chegou. Ecos de Sombra estão mais fortes. Uma cama ajuda a pular a noite.", "Night has fallen. Shade Echoes grow stronger. A bed helps you skip the night."),),
    "d_sandbox": D(("lume", "Modo Sandbox: todos os recursos, receitas e mapas liberados. Construa o que imaginar!", "Sandbox Mode: every resource, recipe and map unlocked. Build anything you imagine!"),),
}

